#![feature(rustc_attrs)]
use verus::prelude::*;

verus! {

    /// Returns `true` if and only if every element of the slice `a` equals `n`.
    /// 
    /// Correctness:
    /// - If the function returns `true`, then for all valid indices `i` in `a`,
    ///   `a[i] == n`.
    /// - If the function returns `false`, then there exists a valid index `i` in `a`
    ///   such that `a[i] != n`.
    pub fn all_elements_equal(a: &[i32], n: i32) -> bool
        ensures
            |res: bool|
                (res ==> forall(|i: usize| i < a.len() ==> a[i] == n))
                && (!res ==> exists(|i: usize| i < a.len() && a[i] != n))
    {
        let mut i: usize = 0;
        // Loop over all indices of `a`
        while i < a.len()
            invariant
                // `i` always stays within bounds
                i <= a.len(),
                // All elements before `i` have been checked and are equal to `n`
                forall(|j: usize| j < i ==> a[j] == n)
            decreases
                // We make progress by increasing `i`
                a.len() - i
        {
            if a[i] != n {
                return false;
            }
            i += 1;
        }
        true
    }

    // Optional: a small proof harness / test case to exercise the spec
    #[proof]
    fn test_all_elements_equal_empty() {
        let a: Vec<i32> = vec![];
        let slice = a.as_slice();
        assert!(all_elements_equal(slice, 42) == true);
        // By the `true`-postcondition, vacuously every element is 42.
    }

    #[proof]
    fn test_all_elements_equal_nonempty() {
        let a = vec![5, 5, 5];
        let slice = a.as_slice();
        assert!(all_elements_equal(slice, 5));
        // Show that if we change one element, the function returns false.
        let mut b = a.clone();
        b[1] = 7;
        let slice2 = b.as_slice();
        assert!(!all_elements_equal(slice2, 5));
        // And by the `false`-postcondition, there exists an index where b[i] != 5.
    }
}